import{_ as e,o as t,c as i,a2 as r}from"./chunks/framework.CWgsre3x.js";const _=JSON.parse('{"title":"Κλειδιά API και ασφαλής ρύθμιση","description":"","frontmatter":{},"headers":[],"relativePath":"el/integrations/api-keys.md","filePath":"el/integrations/api-keys.md"}'),o={name:"el/integrations/api-keys.md"};function l(n,a,s,p,c,d){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="κλειδια-api-και-ασφαλης-ρυθμιση" tabindex="-1">Κλειδιά API και ασφαλής ρύθμιση <a class="header-anchor" href="#κλειδια-api-και-ασφαλης-ρυθμιση" aria-label="Permalink to &quot;Κλειδιά API και ασφαλής ρύθμιση&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Έκδοση αναφοράς</p><p>Έλεγχος πηγαίου κώδικα v0.7.26. Οδηγός διαχειριστή, όχι επιβεβαίωση ζωντανής σύνδεσης. Τα διαπιστευτήρια εγκατάστασης δεν δημοσιεύονται.</p></div><h2 id="αρμοδιοτητες" tabindex="-1">Αρμοδιότητες <a class="header-anchor" href="#αρμοδιοτητες" aria-label="Permalink to &quot;Αρμοδιότητες&quot;">​</a></h2><p>Ο διαχειριστής εταιρείας ελέγχει ετοιμότητα και δικαιώματα. Ο εξουσιοδοτημένος διαχειριστής φιλοξενίας ρυθμίζει μυστικά διακομιστή. Ο κατάλογος διασυνδέσεων και η προβολή πληρωμών δεν αποτελούν γενικό θησαυροφυλάκιο μυστικών ούτε φόρμα εισαγωγής κλειδιών.</p><p>Το API χειριστών χρησιμοποιεί RS256 bearer token και <code>X-Company-Id</code> με ανεξάρτητο έλεγχο εταιρείας και ρόλου. Κλειδί εξωτερικού παρόχου δεν ταυτοποιεί χειριστή. Δείτε <a href="/el/developers/authentication.html">Ταυτοποίηση</a>.</p><h2 id="διαδικασια" tabindex="-1">Διαδικασία <a class="header-anchor" href="#διαδικασια" aria-label="Permalink to &quot;Διαδικασία&quot;">​</a></h2><ol><li>Επιβεβαιώστε εγκατεστημένη έκδοση, εταιρεία, εγκεκριμένη δυνατότητα και δοκιμαστικό λογαριασμό. Εκδώστε χωριστά κλειδιά δοκιμών και παραγωγής από την επίσημη κονσόλα παρόχου.</li><li>Ελέγξτε τα ακριβή ονόματα μεταβλητών της εγκατεστημένης έκδοσης. Οι οδηγοί περιέχουν ονόματα ρυθμίσεων και όχι τιμές μυστικών.</li><li>Αποθηκεύστε τα μυστικά σε περιορισμένο περιβάλλον υπηρεσίας ή υποστηριζόμενη ασφαλή αποθήκη, μόνο για εξουσιοδοτημένη πρόσβαση. Διατηρήστε ρυθμίσεις και δικαιώματα κατά την ενημέρωση. Ποτέ σε Git, δημόσιες ρυθμίσεις, αποθήκευση browser, στιγμιότυπα ή αρχεία υποστήριξης.</li><li>Οι μεταβλητές <code>VITE_</code> ενσωματώνονται στο frontend κατά το build και είναι ορατές. Μόνο δημόσιο κλειδί χάρτη με περιορισμούς ιστοτόπου και API επιτρέπεται. Ποτέ ιδιωτικά κλειδιά, κλειδιά υπογραφής JWT ή κωδικοί βάσης.</li><li>Εφαρμόστε την εγκεκριμένη ρύθμιση μέσω ελεγχόμενης διαδικασίας εγκατάστασης. Μην ενεργοποιείτε δημόσιες κρατήσεις ως παρενέργεια. Ελέγξτε εταιρική απομόνωση, δικαιώματα, αποτυχίες, όρια και ιστορικό με συνθετικά δεδομένα.</li><li>Λάβετε έγκριση ιδιοκτήτη πριν τη ζωντανή ενεργοποίηση. Καταγράψτε πάροχο, περιβάλλον, αναγνωριστικό κλειδιού (όχι τιμή), δικαιώματα, υπεύθυνο, ημερομηνία αλλαγής και αποτέλεσμα δοκιμής.</li></ol><h2 id="αλλαγη-και-προβληματα" tabindex="-1">Αλλαγή και προβλήματα <a class="header-anchor" href="#αλλαγη-και-προβληματα" aria-label="Permalink to &quot;Αλλαγή και προβλήματα&quot;">​</a></h2><p>Σε παραβίαση απενεργοποιήστε τη δυνατότητα, ανακαλέστε το κλειδί στον πάροχο, αντικαταστήστε το ασφαλώς και επαναλάβετε τις δοκιμές. Μην εκτυπώνετε μυστικά. Τα 401/403 ενδέχεται να αφορούν δικαιώματα ή περιβάλλον, ενώ το 429 αφορά όριο χρήσης. Μην παρακάμπτετε ελέγχους. Η επιτυχία ελέγχου υγείας υπηρεσίας δεν αποδεικνύει σύνδεση με πάροχο.</p><p>Δείτε <a href="/el/integrations/third-party-api-setup.html">Ρύθμιση API τρίτων</a> και <a href="/el/security-privacy/">Ασφάλεια και ιδιωτικότητα</a>.</p>',10)])])}const u=e(o,[["render",l]]);export{_ as __pageData,u as default};
